import React from 'react';
import './ToolExecutionPanel.css';

const ToolExecutionPanel = ({ toolCalls }) => {
    if (!toolCalls || toolCalls.length === 0) {
        return (
            <div className="tool-execution-panel empty">
                <h2>Tool Executions</h2>
                <p>No tools have been executed yet.</p>
            </div>
        );
    }

    // Sort tool calls by start time, with most recent first
    const sortedToolCalls = [...toolCalls].sort((a, b) => b.start_time - a.start_time);

    return (
        <div className="tool-execution-panel">
            <h2>Tool Executions</h2>
            <div className="tool-calls-list">
                {sortedToolCalls.map(toolCall => (
                    <div key={toolCall.id} className="tool-call-item">
                        <div className="tool-call-header">
                            <h4>{toolCall.tool_name}</h4>
                            <span className={`tool-status ${toolCall.error ? 'error' : (toolCall.outputs ? 'success' : 'pending')}`}>
                                {toolCall.error ? 'Error' : (toolCall.outputs ? 'Completed' : 'Pending')}
                            </span>
                        </div>
                        <div className="tool-call-inputs">
                            <strong>Inputs:</strong>
                            <div className="inputs-summary">
                                {Object.entries(toolCall.inputs).map(([key, value]) => (
                                    <div key={key} className="input-item">
                                        <span className="input-key">{key}:</span>
                                        <span className="input-value">
                                            {renderInputValue(value)}
                                        </span>
                                    </div>
                                ))}
                            </div>
                        </div>
                        {toolCall.outputs && (
                            <div className="tool-call-outputs">
                                <strong>Results:</strong>
                                <button 
                                    className="toggle-details"
                                    onClick={(e) => toggleDetails(e.target)}
                                >
                                    Show Details
                                </button>
                                <div className="outputs-detail hidden">
                                    <pre>{JSON.stringify(toolCall.outputs, null, 2)}</pre>
                                </div>
                            </div>
                        )}
                        {toolCall.error && (
                            <div className="tool-call-error">
                                <strong>Error:</strong>
                                <div className="error-message">{toolCall.error}</div>
                            </div>
                        )}
                        <div className="tool-call-timing">
                            {formatTimestamp(toolCall.start_time)}
                            {toolCall.end_time && (
                                <span> (took {((toolCall.end_time - toolCall.start_time) * 1000).toFixed(0)}ms)</span>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

const renderInputValue = (value) => {
    if (typeof value === 'object' && value !== null) {
        return JSON.stringify(value).substring(0, 50) + (JSON.stringify(value).length > 50 ? '...' : '');
    }
    return String(value).substring(0, 50) + (String(value).length > 50 ? '...' : '');
};

const formatTimestamp = (timestamp) => {
    const date = new Date(timestamp * 1000);
    return `${date.toLocaleTimeString()}`;
};

const toggleDetails = (button) => {
    const detailsElement = button.nextElementSibling;
    if (detailsElement.classList.contains('hidden')) {
        detailsElement.classList.remove('hidden');
        button.textContent = 'Hide Details';
    } else {
        detailsElement.classList.add('hidden');
        button.textContent = 'Show Details';
    }
};

export default ToolExecutionPanel;
